    {
      "start_block": "B003",
      "end_block": "B009",
      "kind": "hook",
      "description": "Catherine sips wine and schemes with a bare-chested conspirator, vowing to stay on the estate and keep the council paralyzed."
    },
    {
      "start_block": "B022",
      "end_block": "B024",
      "kind": "emotional",
      "description": "Alexander locks eyes with Juliana and declares, 'You are my wife,' vowing nothing breaks their bond before the King and God."
    },
    {
      "start_block": "B027",
      "end_block": "B033",
      "kind": "hook",
      "description": "Lady Ashbourne coldly condemns a weeping Catherine kneeling in the mud, ordering her cast into the road for aiding the poison."
    },
    {
      "start_block": "B053",
      "end_block": "B063",
      "kind": "cliffhanger",
      "description": "Juliana stares unblinking at Catherine and commands her to scrub floors, hearths, and kitchen grease as a scullery maid or be cast out."
    }
